<!doctype html><html><head><meta charset="utf-8"><title>Opening Balance {{ $openingBalance->reference_number }}</title><style>body{font-family:Arial,sans-serif;font-size:12px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #333;padding:6px;text-align:left}.num{text-align:right}</style></head><body><h1>Opening Balance</h1><p><b>Reference:</b> {{ $openingBalance->reference_number }} · <b>Financial Year:</b> {{ $openingBalance->financialYear?->name }} · <b>Business Date:</b> {{ $openingBalance->business_date->format('Y-m-d') }} @include('company.components.nepali-date-display', ['adDate' => $openingBalance->business_date]) · <b>Status:</b> {{ ucfirst($openingBalance->status) }}</p><p><b>Journal:</b> {{ $openingBalance->journal?->journal_no ?? 'Not posted' }} · <b>Accounting Entry:</b> {{ $openingBalance->accountingEntry?->entry_number ?? 'Not posted' }}</p><table><thead><tr><th>#</th><th>Chart Account</th><th>Subledger</th><th class="num">Debit</th><th class="num">Credit</th></tr></thead><tbody>@foreach($openingBalance->lines as $line)<tr><td>{{ $line->line_number }}</td><td>{{ $line->chartAccount->code }} — {{ $line->chartAccount->name }}</td><td>{{ $line->subledger_type ? $line->subledger_type.' #'.$line->subledger_id : '—' }}</td><td class="num">{{ number_format((float)$line->debit,4) }}</td><td class="num">{{ number_format((float)$line->credit,4) }}</td></tr>@endforeach</tbody><tfoot><tr><th colspan="3">Total</th><th class="num">{{ number_format((float)$openingBalance->lines->sum('debit'),4) }}</th><th class="num">{{ number_format((float)$openingBalance->lines->sum('credit'),4) }}</th></tr></tfoot></table><script>window.print()</script></body></html>
